/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 .venv/bin/python -c 'from pathlib import Path
import fitz,json,zipfile,hashlib
d=fitz.open('\\''release_v1/manuscript_v2.pdf'\\'');s='\\''\\n'\\''.join(p.get_text() for p in d)
print('\\''PDF pages'\\'',len(d),'\\''has key claims'\\'',{k:k in s for k in ['\\''84'\\'','\\''0.63'\\'','\\''0.36'\\'','\\''271'\\'','\\''1.34'\\'']},'\\''words'\\'',len(s.split()))
print('\\''PDF start'\\'',s[:2400])
v=json.load(open('\\''release_v1/VALIDATION.json'\\''));z=zipfile.ZipFile('\\''release_v1.zip'\\'');mm=[]
for n,h in v['\\''sha256_16'\\''].items():
 if n in z.namelist() and hashlib.sha256(z.read(n)).hexdigest()[:16]"'!=h:mm.append(n)
print('"'\\''VALIDATION'\\'',v['\\''n_checks'\\''],v['\\''n_pass'\\''],'\\''hash mismatch'\\'',mm)
for p in ['\\''release_v1/README.md'\\'','\\''release_v1/SUBMISSION_CHECKLIST.md'\\'','\\''generations/RELEASE_README.md'\\'']:
 print('\\''FILE'\\'',p)
 for i,l in enumerate(Path(p).read_text().splitlines(),1):print(f'\\''{i}: {l}'\\'')
'"

